# --- Assistant UI, rebuilt without bslib -----------------------------------
# Reuses byok_chat_server (and the module's provider/env helpers) unchanged; only
# the presentation is bslib-free. Inputs/outputs are namespaced under `id` exactly
# as the server expects; the chat is shinychat's web component.
byok_chat_ui_plain <- function(
  id,
  title,
  subtitle = NULL,
  providers = c("gemini", "openai", "anthropic"),
  starters = NULL,
  placeholder = "Ask me anything...",
  height = "100%"
) {
  ns <- NS(id)
  providers <- .byok_chat_providers(providers)
  if (!.byok_chat_packages_ok() || length(providers) == 0) {
    return(tagList(
      div(
        class = "drawer-head",
        div(h2(title)),
        tags$button(
          class = "drawer-close",
          onclick = "DP.closeDrawer('assistant_drawer')",
          HTML("&times;")
        )
      ),
      div(
        class = "drawer-body",
        tags$p(
          "The AI assistant is off because its packages (ellmer, shinychat)",
          "are not installed."
        )
      )
    ))
  }
  choices <- .byok_chat_provider_choices(providers)
  greeting <- if (
    nzchar(.byok_chat_env_first(.byok_chat_provider_meta(providers[1])$env))
  ) {
    paste(
      "Hi! A key was found in your environment - open **Model & key** below,",
      "pick a model, and click **Connect** to start chatting."
    )
  } else {
    paste(
      "Hi! Open **Model & key** below, paste an API key, and click",
      "**Connect** to start chatting."
    )
  }
  if (length(starters) > 0) {
    cards <- paste0(
      "- <span class=\"suggestion submit\">",
      vapply(unname(starters), htmltools::htmlEscape, character(1)),
      "</span>"
    )
    greeting <- paste0(greeting, "\n\n", paste(cards, collapse = "\n"))
  }
  tagList(
    tags$style(HTML(paste0(
      "#",
      ns("chat"),
      " .shiny-tool-request,#",
      ns("chat"),
      " .shiny-tool-result{display:none !important;}"
    ))),
    div(
      class = "drawer-head",
      div(h2(title), if (!is.null(subtitle)) div(class = "sub", subtitle)),
      div(
        style = "display:flex;align-items:center;gap:0.6rem;",
        uiOutput(ns("conn_badge"), inline = TRUE),
        tags$button(
          class = "drawer-close",
          onclick = "DP.closeDrawer('assistant_drawer')",
          HTML("&times;")
        )
      )
    ),
    tags$details(
      class = "byok",
      tags$summary(icon("gear"), " Model & key"),
      div(
        class = "byok-body",
        selectInput(
          ns("provider"),
          "Provider",
          choices = choices,
          selected = unname(choices)[1]
        ),
        uiOutput(ns("key_help")),
        passwordInput(
          ns("api_key"),
          "API key",
          placeholder = "Paste your key (kept in this session only)"
        ),
        selectizeInput(
          ns("model"),
          "Model",
          choices = character(0),
          selected = character(0),
          multiple = FALSE,
          options = list(
            create = TRUE,
            placeholder = "Provider default - pick or type a model"
          )
        ),
        actionButton(
          ns("refresh_models"),
          "List models for this key",
          class = "btn-line"
        ),
        uiOutput(ns("model_source")),
        div(
          style = "display:flex;gap:0.5rem;margin:0.6rem 0;",
          actionButton(ns("connect"), "Connect", class = "btn-line btn-fill"),
          actionButton(ns("forget"), "Forget key", class = "btn-line")
        ),
        uiOutput(ns("cred_status"))
      )
    ),
    div(
      class = "drawer-body chat",
      shinychat::chat_ui(
        ns("chat"),
        height = height,
        placeholder = placeholder,
        greeting = greeting
      )
    )
  )
}

# Client-side glue: vertical-rail page nav (plain show/hide + resize dispatch),
# slide-in drawers + scrim, and the upload-drawer open/close bridge to the server.
DP_JS <- paste0(
  "window.DP={",
  "_scrim:function(){return document.getElementById('scrim');},",
  "openDrawer:function(id){var d=document.getElementById(id);",
  "if(d){d.classList.add('open');DP._scrim().classList.add('show');}},",
  "closeDrawer:function(id){var d=document.getElementById(id);",
  "if(d){d.classList.remove('open');}DP._sync();},",
  "toggleDrawer:function(id){var d=document.getElementById(id);",
  "if(d&&d.classList.contains('open'))DP.closeDrawer(id);else DP.openDrawer(id);},",
  "openQuery:function(){DP.openDrawer('query_drawer');},",
  "openUpload:function(){DP.openDrawer('upload_drawer');},",
  "closeUpload:function(){DP.closeDrawer('upload_drawer');",
  "if(window.Shiny&&Shiny.setInputValue)Shiny.setInputValue('dp_upload_closed',Date.now());},",
  "closeAll:function(){var u=document.getElementById('upload_drawer');",
  "var uo=u&&u.classList.contains('open');",
  "document.querySelectorAll('.drawer.open').forEach(function(d){d.classList.remove('open');});",
  "if(uo&&window.Shiny&&Shiny.setInputValue)Shiny.setInputValue('dp_upload_closed',Date.now());DP._sync();},",
  "_sync:function(){if(!document.querySelector('.drawer.open'))DP._scrim().classList.remove('show');},",
  "_resize:function(){setTimeout(function(){window.dispatchEvent(new Event('resize'));},60);},",
  "nav:function(name){document.querySelectorAll('.rail-nav .navlink[data-page]').forEach(function(a){",
  "a.classList.toggle('active',a.getAttribute('data-page')===name);});",
  "document.querySelectorAll('.page-section[data-page]').forEach(function(s){",
  "s.style.display=(s.getAttribute('data-page')===name)?'block':'none';});",
  "DP._resize();window.scrollTo({top:0,behavior:'smooth'});},",
  # Demo must run on the Workbench with no drawer covering the targets: reset the
  # UI, then fire the `demo` input once the DOM has settled.
  "startDemo:function(){DP.closeAll();DP.nav('Workbench');",
  "setTimeout(function(){if(window.Shiny&&Shiny.setInputValue)",
  "Shiny.setInputValue('demo',Date.now(),{priority:'event'});},420);}",
  "};",
  "document.addEventListener('DOMContentLoaded',function(){",
  "if(window.Shiny){Shiny.addCustomMessageHandler('open_dp_upload',function(x){DP.openUpload();});}});"
)

# Collapsible per-panel guidance: a small muted <details> toggle.
card_help <- function(...) {
  tags$details(
    class = "help",
    tags$summary("How to read this"),
    div(class = "body", ...)
  )
}

# A designed section (bslib-free "card"): eyebrow + title head, then body.
dp_panel <- function(id, eyebrow, title, ..., class = NULL) {
  div(
    class = paste("panel", class),
    id = id,
    div(
      class = "panel-head",
      div(class = "eyebrow", eyebrow),
      h3(class = "panel-title", title)
    ),
    div(class = "panel-body", ...)
  )
}

